INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_music_b005_004', 'topic_was_music_b005_1', 'subj_wassce_music', 'exam_wassce', NULL, NULL, 'Why are notes joined by a tie?', 'multiple_choice', NULL, '["A. An accent or attack on a normally weak part of the metre","B. A minim","C. The crotchet is the beat unit","D. To sustain one sound across their combined values"]', 'D', 'A tie connects notes of the same pitch so they are performed as one uninterrupted duration rather than re-attacked. Therefore the correct answer is D: To sustain one sound across their combined values.', 'easy', '2', '2', '90', NULL, NULL, '1', NULL, 'st_was_music_b005_1', 'Explain', 'AO1', NULL, NULL, 'board_waec');
